import{_ as t}from"./chunks/embed-playground.DUFBb3fy.js";import{_ as a,o as i,c as s,ai as o}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"Embeddings","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/embeddings.md","filePath":"en/guide/embeddings.md"}'),n={name:"en/guide/embeddings.md"};function d(l,e,r,m,c,h){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="embeddings" tabindex="-1">Embeddings <a class="header-anchor" href="#embeddings" aria-label="Permalink to &quot;Embeddings&quot;">​</a></h1><p>The Embeddings page lets you generate text embeddings and visually compare how semantically similar two pieces of text are.</p><p><strong>Sidebar item:</strong> Embeddings <strong>Route:</strong> <code>/embeddings</code></p><p><img src="'+t+'" alt="Embeddings playground"></p><h2 id="what-are-embeddings" tabindex="-1">What Are Embeddings? <a class="header-anchor" href="#what-are-embeddings" aria-label="Permalink to &quot;What Are Embeddings?&quot;">​</a></h2><p>An embedding is a list of numbers (a vector) that represents the meaning of a piece of text. Texts with similar meanings produce vectors that point in similar directions. LLMxRay uses this concept to let you explore semantic similarity hands-on.</p><h2 id="embedding-text" tabindex="-1">Embedding Text <a class="header-anchor" href="#embedding-text" aria-label="Permalink to &quot;Embedding Text&quot;">​</a></h2><ol><li>Select an <strong>embedding model</strong> from the dropdown. Only models with embedding capabilities appear (e.g., <code>nomic-embed-text</code>, <code>all-minilm</code>).</li><li>Enter text in the input area.</li><li>Click <strong>Embed</strong>. The resulting vector is displayed as a visual bar chart.</li></ol><div class="tip custom-block"><p class="custom-block-title">No embedding model?</p><p>If no models appear in the dropdown, you need to pull one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nomic-embed-text</span></span></code></pre></div></div><h2 id="comparing-two-texts" tabindex="-1">Comparing Two Texts <a class="header-anchor" href="#comparing-two-texts" aria-label="Permalink to &quot;Comparing Two Texts&quot;">​</a></h2><ol><li>Enter text in both input areas.</li><li>Click <strong>Compare</strong>. Both texts are embedded and compared.</li><li>The <strong>cosine similarity meter</strong> shows how semantically close the two texts are: <ul><li><strong>1.0</strong> — Identical meaning</li><li><strong>0.7+</strong> — Very similar</li><li><strong>0.3–0.7</strong> — Somewhat related</li><li><strong>&lt; 0.3</strong> — Unrelated</li></ul></li></ol><h2 id="embedding-images" tabindex="-1">Embedding Images <a class="header-anchor" href="#embedding-images" aria-label="Permalink to &quot;Embedding Images&quot;">​</a></h2><p>Since Ollama 0.40, <code>/api/embed</code> accepts an image alongside the text, on models that report both the <code>embedding</code> and <code>vision</code> capabilities. When the selected model does, an <strong>Attach an image</strong> control appears under the playground text box and under each side of the Similarity Calculator. A text-only model shows no image controls at all, because the daemon answers media with a 501.</p><p>What you can do with it:</p><ul><li>Embed a photo and a sentence that describes it, and compare them. Same vector space, so the cosine similarity is meaningful.</li><li>Compare two photos.</li><li>Embed an image alone, with no text.</li></ul><p>Every result shows the <strong>prompt tokens</strong> it cost. An image is a fixed block of tokens on top of the text — measured on embeddinggemma-2: a short sentence cost 7 tokens, the same sentence with a tiny image cost 265. That block is paid whatever the image size.</p><p><strong>The only model that does this today, embeddinggemma-2, runs on Ollama&#39;s MLX runtime, which exists on Apple Silicon only.</strong> On Windows or Linux <code>ollama pull embeddinggemma-2</code> fails with &quot;this model requires MLX support&quot;. To use it from another machine, forward the Mac&#39;s daemon over SSH and point LLMxRay at it in Settings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh -L 11435:localhost:11434 user@your-mac</span></span></code></pre></div><p>then set the Ollama URL to <code>http://localhost:11435/api</code>.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Understanding embeddings</strong> — See what these numbers actually represent</li><li><strong>Testing RAG relevance</strong> — Check if your documents will match user queries</li><li><strong>Exploring synonyms</strong> — See how the model understands semantic relationships</li><li><strong>Educational</strong> — Great for AI/ML coursework on vector representations</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Different embedding models produce different vector dimensions and similarity scores.</li><li>Short, focused texts produce more meaningful comparisons than long paragraphs.</li><li>Results are stored in the session and can be reviewed later.</li></ul>',23)])])}const b=a(n,[["render",d]]);export{u as __pageData,b as default};
